using System.Threading.Channels;
using MailKit.Net.Smtp;
using MailKit.Security;
using Maxx.Application;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using MimeKit;

namespace Maxx.Infrastructure.Email;

// SMTP genérico (decisoes/README.md, E-mail): Mailpit no compose local, provedor da VPS no
// passo 13. A senha do SMTP só por variável de ambiente.
public sealed class EmailOptions
{
    public const string Section = "Email";

    public string Remetente { get; set; } = string.Empty;

    public SmtpOptions Smtp { get; set; } = new();
}

public sealed class SmtpOptions
{
    public string Host { get; set; } = string.Empty;

    public int Porta { get; set; } = 587;

    // None, Auto, StartTls, SslOnConnect (MailKit). None só para o Mailpit local.
    public SecureSocketOptions Seguranca { get; set; } = SecureSocketOptions.StartTls;

    public string? Usuario { get; set; }

    public string? Senha { get; set; }
}

// Uma conexão por mensagem: o volume da fase 1 é de e-mails de recuperação, não de lote.
internal sealed class SmtpEmailSender(IOptions<EmailOptions> options) : IEmailSender
{
    public async Task EnviarAsync(MensagemDeEmail mensagem, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(mensagem);
        var config = options.Value;
        if (string.IsNullOrWhiteSpace(config.Smtp.Host) || string.IsNullOrWhiteSpace(config.Remetente))
        {
            throw new InvalidOperationException("Email__Smtp__Host e Email__Remetente precisam estar configurados.");
        }

        using var mime = new MimeMessage();
        mime.From.Add(MailboxAddress.Parse(config.Remetente));
        mime.To.Add(MailboxAddress.Parse(mensagem.Para));
        mime.Subject = mensagem.Assunto;
        mime.Body = new TextPart("plain") { Text = mensagem.Texto };

        using var smtp = new SmtpClient();
        await smtp.ConnectAsync(config.Smtp.Host, config.Smtp.Porta, config.Smtp.Seguranca, cancellationToken);
        if (!string.IsNullOrEmpty(config.Smtp.Usuario))
        {
            await smtp.AuthenticateAsync(config.Smtp.Usuario, config.Smtp.Senha ?? string.Empty, cancellationToken);
        }

        await smtp.SendAsync(mime, cancellationToken);
        await smtp.DisconnectAsync(quit: true, cancellationToken);
    }
}

// A fila em memória, por réplica. Cheia, recusa a mensagem nova em vez de segurar o pedido:
// o usuário pede o link de novo.
internal sealed partial class FilaDeEmailEmMemoria(ILogger<FilaDeEmailEmMemoria> logger) : IFilaDeEmail
{
    public const int Capacidade = 1000;

    private readonly Channel<MensagemDeEmail> _canal = Channel.CreateBounded<MensagemDeEmail>(
        new BoundedChannelOptions(Capacidade) { SingleReader = true, FullMode = BoundedChannelFullMode.Wait });

    public ChannelReader<MensagemDeEmail> Leitor => _canal.Reader;

    public void Enfileirar(MensagemDeEmail mensagem)
    {
        if (!_canal.Writer.TryWrite(mensagem))
        {
            LogFilaCheia(logger, mensagem.Assunto);
        }
    }

    [LoggerMessage(Level = LogLevel.Error, Message = "Fila de e-mail cheia: \"{Assunto}\" descartado.")]
    private static partial void LogFilaCheia(ILogger logger, string assunto);
}

// Esvazia a fila fora da requisição. Falha de envio fica no log, sem destinatário nem
// texto, e não volta para a fila: sem reenvio até a fila do passo 6.
internal sealed partial class EnvioDeEmailService(
    FilaDeEmailEmMemoria fila, IEmailSender sender, ILogger<EnvioDeEmailService> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var mensagem in fila.Leitor.ReadAllAsync(stoppingToken))
        {
            try
            {
                await sender.EnviarAsync(mensagem, stoppingToken);
                LogEnviado(logger, mensagem.Assunto);
            }
            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
            {
                return;
            }
#pragma warning disable CA1031 // Uma mensagem que falha não pode parar o envio das outras.
            catch (Exception falha)
#pragma warning restore CA1031
            {
                LogFalha(logger, mensagem.Assunto, falha.GetType().Name, falha.Message);
            }
        }
    }

    [LoggerMessage(Level = LogLevel.Information, Message = "E-mail \"{Assunto}\" enviado.")]
    private static partial void LogEnviado(ILogger logger, string assunto);

    [LoggerMessage(Level = LogLevel.Error, Message = "Falha ao enviar o e-mail \"{Assunto}\": {Tipo}: {Erro}")]
    private static partial void LogFalha(ILogger logger, string assunto, string tipo, string erro);
}
namespace Maxx.Application;

// Um e-mail pronto para sair. O texto pode levar segredo (o link de recuperação): nunca
// vai para log, nem pelo ToString.
public sealed record MensagemDeEmail(string Para, string Assunto, string Texto)
{
    public override string ToString() => $"MensagemDeEmail {{ Assunto = {Assunto} }}";
}

// Entrega um e-mail ao servidor SMTP. Chamado só pelo envio em segundo plano.
public interface IEmailSender
{
    Task EnviarAsync(MensagemDeEmail mensagem, CancellationToken cancellationToken);
}

// Envio fora da requisição: quem pede só enfileira e responde. Fila em memória até a fila
// do Postgres do passo 6; perder um e-mail num restart é aceito (decisoes/README.md).
public interface IFilaDeEmail
{
    void Enfileirar(MensagemDeEmail mensagem);
}
using System.Reflection;
using System.Text.Json.Serialization;
using Maxx.Api.Autenticacao;
using Maxx.Api.Demonstracao;
using Maxx.Api.Erros;
using Maxx.Api.Health;
using Maxx.Api.LimiteDeTaxa;
using Maxx.Api.OpenApi;
using Maxx.Infrastructure;
using Maxx.Infrastructure.Persistence;
using Maxx.Infrastructure.Seed;

// `Maxx.Api migrate` roda as migrations e sai. É o comando do contêiner de migração.
var isMigrate = args is ["migrate", ..];

// `Maxx.Api seed <base|demo>` grava os dados de data/ e sai. Idempotente.
var isSeed = args is ["seed", ..];

// A geração do OpenAPI no build sobe a aplicação sem servidor e sem banco.
var isOpenApiGeneration = Assembly.GetEntryAssembly()?.GetName().Name == "GetDocument.Insider";

var builder = WebApplication.CreateBuilder(
    isMigrate ? args[1..] : isSeed ? args[Math.Min(2, args.Length)..] : args);

var connectionString = builder.Configuration.GetConnectionString("Maxx")
    ?? (isOpenApiGeneration ? "Host=openapi-generation" : null)
    ?? throw new InvalidOperationException("ConnectionStrings:Maxx não configurada.");

builder.Services.AddProblemDetails(Erro.Customizar);

// Número só como número: o padrão web aceita "42" em texto, e o contrato viraria
// `number | string` em todo campo numérico do cliente TypeScript.
builder.Services.ConfigureHttpJsonOptions(options =>
    options.SerializerOptions.NumberHandling = JsonNumberHandling.Strict);

builder.Services.AddOpenApi(options => options
    .AddDocumentTransformer((document, _, _) =>
    {
        document.Info.Title = "Maxx API";
        document.Info.Version = "v1";
        return Task.CompletedTask;
    })
    .AddBearerSecurity());
builder.Services.AddInfrastructure(connectionString);
builder.Services.Configure<SeedOptions>(builder.Configuration.GetSection(SeedOptions.Section));

builder.Services.AddSingleton(TimeProvider.System);

// Validação de entrada na borda; a recusa sai em ProblemDetails como o resto.
builder.Services.AddValidation();
builder.Services.AddExceptionHandler<RecusaExceptionHandler>();
builder.Services.AddExceptionHandler<DomainExceptionHandler>();

builder.AddAutenticacao(exigirChave: !isMigrate && !isSeed && !isOpenApiGeneration);
var demonstracao = builder.AddDemonstracao(servindo: !isMigrate && !isSeed && !isOpenApiGeneration, gerandoOpenApi: isOpenApiGeneration);
builder.Services.AddProxyConfiavel(builder.Configuration);
builder.Services.AddLimitesDeTaxa();

var app = builder.Build();

if (isMigrate)
{
    await using var scope = app.Services.CreateAsyncScope();
    await scope.ServiceProvider.GetRequiredService<DatabaseMigrator>().MigrateAsync(CancellationToken.None);
    return 0;
}

if (isSeed)
{
    if (args is not [_, var nomeDoPerfil, ..] || !Enum.TryParse<PerfilDeSeed>(nomeDoPerfil, ignoreCase: true, out var perfil)
        || !Enum.IsDefined(perfil))
    {
        await Console.Error.WriteLineAsync("Uso: Maxx.Api seed <base|demo>");
        return 2;
    }

    await using var scope = app.Services.CreateAsyncScope();
    try
    {
        await scope.ServiceProvider.GetRequiredService<DatabaseSeeder>().SeedAsync(perfil, CancellationToken.None);
    }
    catch (SeedException ex)
    {
        // Dado recusado é resposta esperada, não falha do programa: sem pilha no log.
        await Console.Error.WriteLineAsync(ex.Message);
        return 1;
    }

    return 0;
}

// Primeiro de tudo: o IP e o esquema reais vêm do Caddy, e só dele.
app.UseForwardedHeaders();

// Um formato só de erro: ProblemDetails (RFC 9457).
app.UseExceptionHandler();
app.UseStatusCodePages();

app.UseAuthentication();
app.UseAuthorization();

// Origem única (ADR 0001): toda rota da API vive sob /api, e o Caddy não corta o prefixo.
var api = app.MapGroup("/api");
api.MapHealthEndpoints();

// Contrato versionado: só mudanças aditivas. Fechado por padrão: toda rota de /v1 exige
// login, e a pública diz isso com AllowAnonymous. No grupo, e não numa FallbackPolicy,
// porque a fallback vale também para pedido sem endpoint, e rota inexistente tem de
// continuar 404 (as rotas da demonstração desligada respondem igual a ela).
var v1 = api.MapGroup("/v1").RequireAuthorization();
v1.MapEuEndpoints();
v1.MapTermoDeUsoEndpoints();
v1.MapGroup("/auth").AllowAnonymous().MapCadastroEndpoints().MapLoginEndpoints().MapRecuperacaoEndpoints();
if (demonstracao)
{
    v1.MapDemonstracaoEndpoints();
}

if (app.Environment.IsDevelopment())
{
    api.MapOpenApi("/openapi/{documentName}.json");
}

await app.RunAsync();
return 0;
namespace Maxx.Domain.Catalogo;

// Um item do catálogo, como está em data/catalogo/. Tier e pontos são fixos: quem
// concede escolhe o item, ninguém digita valor. A raridade não está aqui: é derivada da
// escassez pelo worker.
public abstract record ItemCatalogo
{
    public required string Codigo { get; init; }

    public required string Nome { get; init; }

    public required string Descricao { get; init; }

    public required Tier Tier { get; init; }

    public required int Pontos { get; init; }

    public string? Familia { get; init; }

    public int? OrdemNaFamilia { get; init; }

    public string? RestricaoCurso { get; init; }

    public Vigencia Vigencia { get; init; } = Vigencia.Sempre;

    public abstract TipoDeItem Tipo { get; }
}

public sealed record Vigencia(DateOnly? Inicio, DateOnly? Fim)
{
    public static Vigencia Sempre { get; } = new(null, null);
}

public sealed record ItemMedalha : ItemCatalogo
{
    public override TipoDeItem Tipo => TipoDeItem.Medalha;

    public required BaseDaMedalha Base { get; init; }

    public required Periodo PeriodoDeReferencia { get; init; }

    public required bool Repetivel { get; init; }

    // Quantas vezes por aluno, matéria e período de referência.
    public required int LimitePorPeriodo { get; init; }

    public required IReadOnlyList<CampoDeDeduplicacao> ChaveDeDeduplicacao { get; init; }
}

public sealed record ItemPremioParticipacao : ItemCatalogo
{
    public override TipoDeItem Tipo => TipoDeItem.PremioParticipacao;

    public required string TipoDeEvento { get; init; }

    public required FormaDoEvento FormaDoEvento { get; init; }

    public required bool ExigeFoto { get; init; }

    public Periodo PeriodoDeReferencia { get; init; } = Periodo.Evento;

    public required IReadOnlyList<CampoDeDeduplicacao> ChaveDeDeduplicacao { get; init; }
}

public sealed record ItemConquista : ItemCatalogo
{
    public override TipoDeItem Tipo => TipoDeItem.Conquista;

    public required Periodo Periodo { get; init; }

    public required Gatilho Gatilho { get; init; }

    public required RegraDeConquista Regra { get; init; }
}
namespace Maxx.Infrastructure.Persistence;

// Uma linha de item_catalogo: os três tipos numa tabela só, com coluna de tipo. Campos
// comuns sempre preenchidos; os específicos de cada tipo, nulos nos outros (uma check
// constraint cobra isso). Enumerações em texto camelCase, como no JSON de origem.
//
// Não é o modelo do domínio: os itens do domínio são imutáveis, e a versão é assunto do
// seeder (sobe quando o conteúdo muda; ADR 0007).
public sealed class ItemCatalogoRow
{
    public required string Codigo { get; set; }

    public required string Tipo { get; set; }

    public int Versao { get; set; } = 1;

    public required string Nome { get; set; }

    public required string Descricao { get; set; }

    public required string Tier { get; set; }

    public int Pontos { get; set; }

    // periodoDeReferencia na medalha e no prêmio de participação; periodo na conquista.
    public required string Periodo { get; set; }

    public string? FamiliaCodigo { get; set; }

    public int? OrdemNaFamilia { get; set; }

    public string? RestricaoCurso { get; set; }

    public DateOnly? VigenciaInicio { get; set; }

    public DateOnly? VigenciaFim { get; set; }

    // Medalha e prêmio de participação.
    public string[]? ChaveDeDeduplicacao { get; set; }

    // Medalha.
    public string? Base { get; set; }

    public bool? Repetivel { get; set; }

    public int? LimitePorPeriodo { get; set; }

    // Prêmio de participação.
    public string? TipoDeEvento { get; set; }

    public string? FormaDoEvento { get; set; }

    public bool? ExigeFoto { get; set; }

    // Conquista. A regra é dado que o avaliador interpreta: jsonb, no formato do catálogo.
    public string? Gatilho { get; set; }

    public string? Regra { get; set; }
}

public sealed class FamiliaRow
{
    public required string Codigo { get; set; }

    public required string Nome { get; set; }

    public required string Descricao { get; set; }

    public int Passos { get; set; }
}

