using Maxx.Application;
using Maxx.Application.Autenticacao;
using Maxx.Application.Autorizacao;
using Maxx.Application.Demonstracao;
using Maxx.Infrastructure.Autenticacao;
using Maxx.Infrastructure.Autorizacao;
using Maxx.Infrastructure.Demonstracao;
using Maxx.Infrastructure.Email;
using Maxx.Infrastructure.Persistence;
using Maxx.Infrastructure.Seed;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Npgsql;

namespace Maxx.Infrastructure;

public static class DependencyInjection
{
    public static IServiceCollection AddInfrastructure(this IServiceCollection services, string connectionString)
    {
        services.AddNpgsqlDataSource(connectionString);

        services.AddDbContext<MaxxDbContext>((provider, options) =>
            MaxxDbContext.Configure(options, builder => builder.UseNpgsql(
                provider.GetRequiredService<NpgsqlDataSource>(),
                npgsql => npgsql.MigrationsHistoryTable(MaxxDbContext.MigrationsHistoryTable))));

        services.AddScoped<DatabaseMigrator>();
        services.AddScoped<DatabaseSeeder>();

        services.AddSingleton<ISenhaHasher, Argon2idSenhaHasher>();
        services.AddSingleton<ITokenGenerator, TokenGenerator>();

        services.AddScoped<IUnitOfWork, UnitOfWork>();
        services.AddScoped<ICadastroElegivelRepository, CadastroElegivelRepository>();
        services.AddScoped<IUsuarioRepository, UsuarioRepository>();
        services.AddScoped<ITermoDeUsoRepository, TermoDeUsoRepository>();
        services.AddScoped<IFamiliaDeSessaoRepository, FamiliaDeSessaoRepository>();
        services.AddScoped<IEscopoDeTurma, EscopoDeTurma>();
        services.AddScoped<IRecuperacaoDeSenhaRepository, RecuperacaoDeSenhaRepository>();
        services.AddScoped<IDemonstracaoRepository, DemonstracaoRepository>();

        // E-mail fora da requisição. As opções (EmailOptions) vêm da borda.
        services.AddSingleton<FilaDeEmailEmMemoria>();
        services.AddSingleton<IFilaDeEmail>(provider => provider.GetRequiredService<FilaDeEmailEmMemoria>());
        services.AddSingleton<IEmailSender, SmtpEmailSender>();
        services.AddHostedService<EnvioDeEmailService>();

        // Toda verificação registrada aqui entra no /ready.
        services.AddHealthChecks()
            .AddCheck<DatabaseReadinessCheck>("database", timeout: TimeSpan.FromSeconds(3));

        return services;
    }
}
using Microsoft.EntityFrameworkCore;

namespace Maxx.Infrastructure.Persistence;

// O esquema cresce por passo: cada passo traz a sua migration. Sem DbSet: as entidades
// entram pelas configurações, cada uma com nome de tabela explícito, e o acesso é por
// Set<T>(). Um DbSet no plural vazaria para o nome das chaves estrangeiras.
public sealed class MaxxDbContext(DbContextOptions<MaxxDbContext> options) : DbContext(options)
{
    public const string MigrationsHistoryTable = "__ef_migrations_history";

    public static void Configure(DbContextOptionsBuilder options, Action<DbContextOptionsBuilder> useNpgsql)
    {
        useNpgsql(options);
        options.UseSnakeCaseNamingConvention();
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.HasPostgresExtension("citext");
        modelBuilder.ApplyConfigurationsFromAssembly(typeof(MaxxDbContext).Assembly);
    }
}
using Maxx.Application;
using Microsoft.EntityFrameworkCore;
using Npgsql;

namespace Maxx.Infrastructure.Persistence;

// Grava o que o escopo acumulou. Unicidade violada vira ConflitoDeUnicidadeException com
// o nome da regra, para a Application responder com o código certo sem conhecer o banco.
internal sealed class UnitOfWork(MaxxDbContext db) : IUnitOfWork
{
    private static readonly Dictionary<string, Unicidade> _porIndice = new(StringComparer.Ordinal)
    {
        ["ix_usuario_cadastro_elegivel_id"] = Unicidade.ContaPorCadastro,
        ["pk_prefixo_reservado"] = Unicidade.Prefixo,
    };

    public async Task SalvarAsync(CancellationToken cancellationToken)
    {
        try
        {
            await db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException falha) when (falha.InnerException is PostgresException
        {
            SqlState: PostgresErrorCodes.UniqueViolation,
        } postgres)
        {
            throw new ConflitoDeUnicidadeException(
                _porIndice.GetValueOrDefault(postgres.ConstraintName ?? string.Empty, Unicidade.Outra), falha);
        }
        catch (DbUpdateConcurrencyException falha)
        {
            throw new ConflitoDeConcorrenciaException("A linha mudou desde a leitura.", falha);
        }
    }

    public void Descartar() => db.ChangeTracker.Clear();
}
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.Extensions.Logging;
using Npgsql;

namespace Maxx.Infrastructure.Persistence;

// Roda no contêiner de migração (`Maxx.Api migrate`), nunca no startup da aplicação.
public sealed partial class DatabaseMigrator(MaxxDbContext db, ILogger<DatabaseMigrator> logger)
{
    // Chave fixa do advisory lock de migração. Qualquer valor serve, desde que seja
    // sempre o mesmo e nenhum outro lock do Maxx o use.
    public const long AdvisoryLockKey = 0x4D41_5858_0001;

    public async Task MigrateAsync(CancellationToken cancellationToken)
    {
        // O lock é da sessão: a mesma conexão precisa segurá-lo, migrar e soltá-lo.
        await db.Database.OpenConnectionAsync(cancellationToken);
        try
        {
            var connection = (NpgsqlConnection)db.Database.GetDbConnection();

            LogWaitingForLock(logger);
            await ExecuteAsync(connection, "SELECT pg_advisory_lock(@key)", cancellationToken);
            try
            {
                // Sem a tabela de histórico, o EF consulta uma tabela inexistente e registra erro.
                await db.GetService<IHistoryRepository>().CreateIfNotExistsAsync(cancellationToken);

                var pending = (await db.Database.GetPendingMigrationsAsync(cancellationToken)).ToList();
                LogPending(logger, pending.Count);
                await db.Database.MigrateAsync(cancellationToken);
                LogDone(logger);
            }
            finally
            {
                await ExecuteAsync(connection, "SELECT pg_advisory_unlock(@key)", CancellationToken.None);
            }
        }
        finally
        {
            await db.Database.CloseConnectionAsync();
        }
    }

    private static async Task ExecuteAsync(NpgsqlConnection connection, string sql, CancellationToken cancellationToken)
    {
        await using var command = new NpgsqlCommand(sql, connection);
        command.Parameters.AddWithValue("key", AdvisoryLockKey);
        await command.ExecuteNonQueryAsync(cancellationToken);
    }

    [LoggerMessage(Level = LogLevel.Information, Message = "Aguardando o lock de migração.")]
    private static partial void LogWaitingForLock(ILogger logger);

    [LoggerMessage(Level = LogLevel.Information, Message = "Lock obtido; {Count} migration(s) pendente(s).")]
    private static partial void LogPending(ILogger logger, int count);

    [LoggerMessage(Level = LogLevel.Information, Message = "Migração concluída.")]
    private static partial void LogDone(ILogger logger);
}
