namespace Maxx.Domain.Academico;

// Responde em qual bimestre e semestre cai um instante. Fora deles (férias, recesso),
// a resposta é nula: nenhum fato acadêmico acontece ali.
public sealed class Calendario
{
    private readonly List<AnoLetivo> _anos;

    public Calendario(IEnumerable<AnoLetivo> anos)
    {
        ArgumentNullException.ThrowIfNull(anos);

        _anos = [.. anos.OrderBy(ano => ano.Ano)];
        for (var i = 1; i < _anos.Count; i++)
        {
            if (_anos[i].Ano == _anos[i - 1].Ano)
            {
                throw new DomainException($"O ano letivo {_anos[i].Ano} aparece duas vezes no calendário.");
            }

            if (_anos[i].Inicio <= _anos[i - 1].Fim)
            {
                throw new DomainException(
                    $"O ano letivo {_anos[i].Ano} começa antes de o {_anos[i - 1].Ano} terminar.");
            }
        }
    }

    public IReadOnlyList<AnoLetivo> Anos => _anos;

    public SemestreLetivo? SemestreEm(DateTimeOffset instante)
    {
        var data = FusoHorario.DataLocal(instante);
        return _anos.SelectMany(ano => ano.Semestres).FirstOrDefault(semestre => semestre.Contem(data));
    }

    public Bimestre? BimestreEm(DateTimeOffset instante)
    {
        var data = FusoHorario.DataLocal(instante);
        return _anos.SelectMany(ano => ano.Bimestres).FirstOrDefault(bimestre => bimestre.Contem(data));
    }
}
namespace Maxx.Domain.Academico;

// Numerado de 1 a 4 dentro do ano letivo: o semestre 1 tem os bimestres 1 e 2, o
// semestre 2 tem o 3 e o 4. Datas inclusivas nas duas pontas.
public sealed class Bimestre
{
    public const int PorAno = SemestreLetivo.PorAno * SemestreLetivo.BimestresPorSemestre;

    // Para o EF Core materializar do banco.
    private Bimestre()
    {
    }

    public Bimestre(int numero, DateOnly inicio, DateOnly fim)
    {
        if (numero is < 1 or > PorAno)
        {
            throw new DomainException($"Bimestre {numero} não existe: o ano letivo tem {PorAno}.");
        }

        if (fim < inicio)
        {
            throw new DomainException($"Bimestre {numero} termina ({fim}) antes de começar ({inicio}).");
        }

        Id = Guid.CreateVersion7();
        Numero = numero;
        Inicio = inicio;
        Fim = fim;
    }

    public Guid Id { get; private set; }

    public int Numero { get; private set; }

    public DateOnly Inicio { get; private set; }

    public DateOnly Fim { get; private set; }

    public bool Contem(DateOnly data) => data >= Inicio && data <= Fim;

    // Só pelo AnoLetivo, que valida o ano corrigido inteiro antes de copiar as datas.
    internal bool Redatar(DateOnly inicio, DateOnly fim)
    {
        if (inicio == Inicio && fim == Fim)
        {
            return false;
        }

        Inicio = inicio;
        Fim = fim;
        return true;
    }
}
namespace Maxx.Domain.Academico;

// O semestre letivo (2026/2) corta ranking e conquistas. Não confundir com o semestre do
// aluno, que é só perfil. Começa no primeiro dia do primeiro bimestre e termina no último
// dia do segundo: férias e recesso ficam fora.
public sealed class SemestreLetivo
{
    public const int PorAno = 2;
    public const int BimestresPorSemestre = 2;

    private readonly List<Bimestre> _bimestres;

    // Para o EF Core materializar do banco.
    private SemestreLetivo() => _bimestres = [];

    public SemestreLetivo(int ano, int numero, Bimestre primeiro, Bimestre segundo)
    {
        ArgumentNullException.ThrowIfNull(primeiro);
        ArgumentNullException.ThrowIfNull(segundo);

        if (ano < 1)
        {
            throw new DomainException($"Ano {ano} inválido.");
        }

        if (numero is < 1 or > PorAno)
        {
            throw new DomainException($"Semestre {numero} não existe: o ano letivo tem {PorAno}.");
        }

        var esperado = ((numero - 1) * BimestresPorSemestre) + 1;
        if (primeiro.Numero != esperado || segundo.Numero != esperado + 1)
        {
            throw new DomainException(
                $"O semestre {ano}/{numero} tem os bimestres {esperado} e {esperado + 1}, " +
                $"não {primeiro.Numero} e {segundo.Numero}.");
        }

        if (segundo.Inicio <= primeiro.Fim)
        {
            throw new DomainException(
                $"No semestre {ano}/{numero}, o bimestre {segundo.Numero} começa antes de o {primeiro.Numero} terminar.");
        }

        Id = Guid.CreateVersion7();
        Ano = ano;
        Numero = numero;
        _bimestres = [primeiro, segundo];
    }

    public Guid Id { get; private set; }

    public int Ano { get; private set; }

    public int Numero { get; private set; }

    public string Codigo => $"{Ano}/{Numero}";

    // Ordenado na leitura: vindo do banco, a coleção não garante ordem.
    public IReadOnlyList<Bimestre> Bimestres => [.. _bimestres.OrderBy(bimestre => bimestre.Numero)];

    public DateOnly Inicio => _bimestres.Min(bimestre => bimestre.Inicio);

    public DateOnly Fim => _bimestres.Max(bimestre => bimestre.Fim);

    public bool Contem(DateOnly data) => data >= Inicio && data <= Fim;
}
namespace Maxx.Domain.Academico;

// Matéria mais semestre letivo. Professores vinculados e alunos matriculados por turma.
public sealed class Turma
{
    // Para o EF Core materializar do banco.
    private Turma() => Materia = null!;

    public Turma(Materia materia, SemestreLetivo semestre)
    {
        ArgumentNullException.ThrowIfNull(materia);
        ArgumentNullException.ThrowIfNull(semestre);

        Id = Guid.CreateVersion7();
        Materia = materia;
        MateriaId = materia.Id;
        SemestreLetivoId = semestre.Id;
    }

    public Guid Id { get; private set; }

    public Guid MateriaId { get; private set; }

    public Materia Materia { get; private set; }

    public Guid SemestreLetivoId { get; private set; }
}
namespace Maxx.Domain.Academico;

// Vínculo aluno e turma. Única fonte de "quantas matérias o aluno tem no período".
public sealed class Matricula
{
    // Para o EF Core materializar do banco.
    private Matricula()
    {
    }

    public Matricula(CadastroElegivel aluno, Turma turma)
    {
        ArgumentNullException.ThrowIfNull(aluno);
        ArgumentNullException.ThrowIfNull(turma);

        if (!aluno.EhAluno)
        {
            throw new DomainException($"Só aluno se matricula em turma; {aluno.Email} é {aluno.Papeis}.");
        }

        if (turma.Materia.CursoId != aluno.CursoId)
        {
            throw new DomainException(
                $"{aluno.Email} não pode se matricular em {turma.Materia.Nome}: a matéria é de outro curso.");
        }

        Id = Guid.CreateVersion7();
        AlunoId = aluno.Id;
        TurmaId = turma.Id;
    }

    public Guid Id { get; private set; }

    // Aponta para o CadastroElegivel: a faculdade matricula antes de o aluno ter conta.
    public Guid AlunoId { get; private set; }

    public Guid TurmaId { get; private set; }
}
namespace Maxx.Domain.Academico;

// Professor cadastrado por turma, a cada semestre. É a fonte do escopo de turma checado
// no banco a cada mutação de prêmio.
public sealed class VinculoProfessor
{
    // Para o EF Core materializar do banco.
    private VinculoProfessor()
    {
    }

    public VinculoProfessor(CadastroElegivel professor, Turma turma)
    {
        ArgumentNullException.ThrowIfNull(professor);
        ArgumentNullException.ThrowIfNull(turma);

        if (!professor.EhProfessor)
        {
            throw new DomainException($"Só professor se vincula a turma; {professor.Email} é {professor.Papeis}.");
        }

        Id = Guid.CreateVersion7();
        ProfessorId = professor.Id;
        TurmaId = turma.Id;
    }

    public Guid Id { get; private set; }

    public Guid ProfessorId { get; private set; }

    public Guid TurmaId { get; private set; }
}
namespace Maxx.Domain.Academico;

// Instantes são guardados em UTC; as fronteiras de bimestre, semestre e ano são datas
// interpretadas em America/Sao_Paulo.
public static class FusoHorario
{
    public static TimeZoneInfo SaoPaulo { get; } = TimeZoneInfo.FindSystemTimeZoneById("America/Sao_Paulo");

    public static DateOnly DataLocal(DateTimeOffset instante) =>
        DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(instante, SaoPaulo).DateTime);
}
namespace Maxx.Domain.Catalogo;

public enum TipoDeItem
{
    Medalha,
    PremioParticipacao,
    Conquista,
}

// Medalha usa bimestre ou semestre; prêmio de participação, o evento; conquista,
// bimestre, semestre, ano ou curso.
public enum Periodo
{
    Bimestre,
    Semestre,
    Ano,
    Curso,
    Evento,
}

public enum BaseDaMedalha
{
    Nota,
    Presenca,
}

public enum FormaDoEvento
{
    Pontual,
    Periodo,
}

public enum Gatilho
{
    PorFato,
    FechamentoDePeriodo,
}

public enum CampoDeDeduplicacao
{
    Aluno,
    Item,
    Materia,
    Bimestre,
    Semestre,
    Ocorrencia,
    Evento,
    DataDoEvento,
}
namespace Maxx.Domain.Catalogo;

// O metal do medalhão. Define a faixa de pontos do item; não existe sub-tier.
public enum Tier
{
    Bronze,
    Prata,
    Ouro,
    Diamante,
}

public readonly record struct FaixaDePontos(int Minimo, int Maximo)
{
    public bool Contem(int pontos) => pontos >= Minimo && pontos <= Maximo;

    public override string ToString() => $"{Minimo} a {Maximo}";
}

public static class Tiers
{
    public static FaixaDePontos Faixa(Tier tier) => tier switch
    {
        Tier.Bronze => new(1, 30),
        Tier.Prata => new(31, 70),
        Tier.Ouro => new(71, 100),
        Tier.Diamante => new(101, 150),
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null),
    };
}
namespace Maxx.Domain;

// Regra de produto violada. A borda traduz para o formato único de erro; a mensagem é
// para quem lê o log, não para o usuário final.
public sealed class DomainException : Exception
{
    public DomainException()
    {
    }

    public DomainException(string message) : base(message)
    {
    }

    public DomainException(string message, Exception innerException) : base(message, innerException)
    {
    }
}

