    [Fact]
    public void Item_restrito_a_outro_curso_e_recusado()
    {
        var deAdm = CatalogoDeTeste.M01 with { RestricaoCurso = "ADM" };

        Assert.Equal(RecusaDaConcessao.ItemDeOutroCurso, Conceder(deAdm, Aluna()).Recusa);
