using System.ComponentModel.DataAnnotations;
using Maxx.Api.Autenticacao;
using Maxx.Api.LimiteDeTaxa;
using Maxx.Application.Demonstracao;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Maxx.Api.Demonstracao;

// A flag da demonstração (CLAUDE.md, Segurança): desligada por padrão e ausente de todo
// appsettings versionado. Liga-se só por variável de ambiente, no compose da apresentação.
public sealed class DemoOptions
{
    public const string Section = "Demo";

    public bool Habilitada { get; set; }

    // Gravado em cada aluno de demonstração criado enquanto vale: a chave da purga.
    public string? Lote { get; set; }
}

internal static class DemonstracaoEndpoints
{
    // Devolve se as rotas devem existir. Desligada, elas nem são mapeadas: a resposta é o
    // 404 de uma rota inexistente, byte a byte. A geração do OpenAPI as mapeia mesmo assim,
    // para o cliente ter os tipos da tela do passo 5.
    public static bool AddDemonstracao(this WebApplicationBuilder builder, bool servindo, bool gerandoOpenApi)
    {
        var opcoes = builder.Configuration.GetSection(DemoOptions.Section).Get<DemoOptions>() ?? new DemoOptions();
        if (opcoes.Habilitada && servindo && string.IsNullOrWhiteSpace(opcoes.Lote))
        {
            throw new InvalidOperationException(
                $"{DemoOptions.Section}__Habilitada sem {DemoOptions.Section}__Lote: defina o lote da apresentação.");
        }

        builder.Services.AddSingleton(new ConfiguracaoDaDemonstracao(opcoes.Lote?.Trim() ?? string.Empty));
        builder.Services.AddScoped<DemonstracaoHandler>();

        return opcoes.Habilitada || gerandoOpenApi;
    }

    public static IEndpointRouteBuilder MapDemonstracaoEndpoints(this IEndpointRouteBuilder v1)
    {
        var demo = v1.MapGroup("/demo").WithTags("Demonstracao").AllowAnonymous();

        demo.MapGet("", CursosAsync).WithName("GetDemonstracao");

        demo.MapPost("/alunos", RegistrarAsync)
            .WithName("RegistrarAlunoDeDemonstracao")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict)
            .ComLimiteDeTaxa(Limite.RegistroDeDemonstracaoPorIp, contexto => LimiteDeTaxaExtensions.Ip(contexto.HttpContext));

        demo.MapPost("/entrar", EntrarAsync)
            .WithName("EntrarNaDemonstracao")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status401Unauthorized);

        return v1;
    }

    // Responder já diz que a demonstração está ligada; o corpo traz os cursos da escolha.
    private static async Task<Ok<DemonstracaoResponse>> CursosAsync(
        DemonstracaoHandler handler, CancellationToken cancellationToken) =>
        TypedResults.Ok(new DemonstracaoResponse(
            [.. (await handler.CursosAsync(cancellationToken)).Select(curso => new CursoDeDemonstracao(curso.Sigla, curso.Nome))]));

    private static async Task<Created<RegistroDeDemonstracaoResponse>> RegistrarAsync(
        RegistroDeDemonstracaoRequest pedido, DemonstracaoHandler handler, HttpContext httpContext, CancellationToken cancellationToken)
    {
        var registro = await handler.RegistrarAsync(pedido.Nome, pedido.Curso, pedido.VersaoDoTermo, cancellationToken);
        return TypedResults.Created(
            (string?)null,
            new RegistroDeDemonstracaoResponse(registro.ChaveDoDispositivo, SessaoHttp.Escrever(httpContext, registro.Sessao)));
    }

    private static async Task<Ok<SessaoResponse>> EntrarAsync(
        EntradaDeDemonstracaoRequest pedido, DemonstracaoHandler handler, HttpContext httpContext, CancellationToken cancellationToken)
    {
        var sessao = await handler.EntrarAsync(pedido.ChaveDoDispositivo, cancellationToken);
        return TypedResults.Ok(SessaoHttp.Escrever(httpContext, sessao));
    }
}

public sealed record DemonstracaoResponse(IReadOnlyList<CursoDeDemonstracao> Cursos);

public sealed record CursoDeDemonstracao(string Sigla, string Nome);

// O nome tem a forma do nome de exibição, conferida no domínio.
public sealed record RegistroDeDemonstracaoRequest(
    [property: Required(AllowEmptyStrings = true), StringLength(240)] string Nome,
    [property: Required, StringLength(16)] string Curso,
    [property: Range(1, int.MaxValue)] int VersaoDoTermo);

public sealed record EntradaDeDemonstracaoRequest([property: Required, StringLength(128)] string ChaveDoDispositivo)
{
    public override string ToString() => "EntradaDeDemonstracaoRequest { }";
}

// A chave do dispositivo vai sempre no corpo, na web também: o app a guarda para voltar,
// e ela só abre a conta de demonstração.
public sealed record RegistroDeDemonstracaoResponse(string ChaveDoDispositivo, SessaoResponse Sessao)
{
    public override string ToString() => "RegistroDeDemonstracaoResponse { }";
}
using Microsoft.AspNetCore.Authorization;

namespace Maxx.Api.Autenticacao;

// As policies por papel. O papel vem do token, que o tirou do cadastro elegível; o escopo
// de turma do professor nunca: esse é conferido no banco (IEscopoDeTurma).
internal static class Politicas
{
    public const string Aluno = "aluno";

    public const string Professor = "professor";

    public const string Instituicao = "instituicao";

    public static void Configurar(AuthorizationOptions options)
    {
        ArgumentNullException.ThrowIfNull(options);

        options.AddPolicy(Aluno, policy => policy.RequireAuthenticatedUser().RequireRole(Aluno));
        options.AddPolicy(Professor, policy => policy.RequireAuthenticatedUser().RequireRole(Professor));
        options.AddPolicy(Instituicao, policy => policy.RequireAuthenticatedUser().RequireRole(Instituicao));
    }
}
namespace Maxx.Application.Autenticacao;

// Os códigos de recusa da autenticação, como o cliente os recebe em ProblemDetails.
public static class CodigosDeRecusa
{
    public const string CadastroNaoEncontrado = "cadastro-nao-encontrado";

    // O RA já tem conta: o cliente leva à recuperação de senha (produto.md 2.5).
    public const string ContaExistente = "conta-existente";

    public const string PrefixoInvalido = "prefixo-invalido";

    public const string PrefixoIndisponivel = "prefixo-indisponivel";

    public const string SenhaForaDaPolitica = "senha-fora-da-politica";

    public const string NomeDeExibicaoInvalido = "nome-de-exibicao-invalido";

    // Nenhuma versão do termo de uso publicada: o seed base não rodou.
    public const string TermoIndisponivel = "termo-indisponivel";

    // O aceite é de uma versão que não é a vigente: o cliente busca o texto novo e pede o
    // aceite de novo.
    public const string TermoDesatualizado = "termo-desatualizado";

    // Usuário inexistente, conta ainda sem senha, senha errada, professor por RA: a mesma
    // resposta, para não dizer quem tem conta (ADR 0006).
    public const string CredenciaisInvalidas = "credenciais-invalidas";

    // Refresh ausente, desconhecido, expirado, de família revogada ou reusado: em todos os
    // casos o cliente volta ao login.
    public const string SessaoInvalida = "sessao-invalida";

    // Token de recuperação desconhecido, expirado, já usado ou invalidado por outro pedido
    // concluído: em todos os casos o cliente oferece pedir um link novo.
    public const string RecuperacaoInvalida = "recuperacao-invalida";

    // Demonstração: curso que não existe ou sem turma no semestre vigente.
    public const string CursoDeDemonstracaoIndisponivel = "curso-indisponivel";

    // Demonstração: muita gente com o mesmo nome entrando junto, e as tentativas acabaram.
    // O cliente oferece tentar de novo.
    public const string RegistroSimultaneo = "registro-simultaneo";

    // Demonstração: a chave guardada no dispositivo não abre conta nenhuma.
    public const string ChaveDoDispositivoInvalida = "chave-invalida";
}
using Maxx.Application;
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

namespace Maxx.Api.Erros;

// Recusa da Application vira o status do tipo e o código dela, no formato único.
internal sealed partial class RecusaExceptionHandler(
    IProblemDetailsService problemDetails, ILogger<RecusaExceptionHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
    {
        if (exception is not RecusaException recusa)
        {
            return false;
        }

        LogRecusada(logger, recusa.Codigo, recusa.Message);

        var status = recusa.Tipo switch
        {
            TipoDeRecusa.NaoEncontrado => StatusCodes.Status404NotFound,
            TipoDeRecusa.Conflito => StatusCodes.Status409Conflict,
            TipoDeRecusa.NaoAutorizado => StatusCodes.Status401Unauthorized,
            _ => StatusCodes.Status400BadRequest,
        };

        httpContext.Response.StatusCode = status;
        return await problemDetails.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            Exception = exception,
            ProblemDetails = new ProblemDetails
            {
                Status = status,
                Extensions = { [Erro.CampoCodigo] = recusa.Codigo },
            },
        });
    }

    [LoggerMessage(Level = LogLevel.Information, Message = "Pedido recusado ({Codigo}): {Motivo}")]
    private static partial void LogRecusada(ILogger logger, string codigo, string motivo);
}

