internal sealed class ConsultaDePremios(MaxxDbContext db) : IConsultaDePremios
{
    public async Task<PremiosDoAluno?> DoAlunoAsync(Guid alunoId, CancellationToken cancellationToken)
    {
        var aluno = await (
                from usuario in db.Set<Usuario>()
                join cadastro in db.Set<CadastroElegivel>() on usuario.CadastroElegivelId equals cadastro.Id
                join curso in db.Set<Curso>() on cadastro.CursoId equals curso.Id
                where usuario.Id == alunoId && usuario.Papeis == Papeis.Aluno
                select new { curso.Sigla })
            .SingleOrDefaultAsync(cancellationToken);
        if (aluno is null)
        {
            return null;
        }

        var medalhas = await (
                from medalha in db.Set<Medalha>()
                join materia in db.Set<Materia>() on medalha.MateriaId equals materia.Id
                join bimestre in db.Set<Bimestre>() on medalha.BimestreId equals bimestre.Id
                where medalha.AlunoId == alunoId && medalha.AnuladaEm == null
                orderby medalha.ConcedidaEm descending
                select new { medalha.Id, medalha.ItemCodigo, medalha.Tier, medalha.Pontos, Materia = materia.Nome, bimestre.Numero, medalha.ConcedidaEm })
            .ToListAsync(cancellationToken);
        var obtidos = medalhas.ToLookup(
            medalha => medalha.ItemCodigo,
            medalha => new PremioObtido(medalha.Id, medalha.Tier, medalha.Pontos, medalha.Materia, medalha.Numero, medalha.ConcedidaEm));

        var raridades = await db.Set<RaridadeDoItemRow>().AsNoTracking()
            .ToDictionaryAsync(linha => linha.ItemCodigo, cancellationToken);
        var itens = await db.Set<ItemCatalogoRow>().AsNoTracking().OrderBy(item => item.Codigo).ToListAsync(cancellationToken);
        var familias = await db.Set<FamiliaRow>().AsNoTracking().OrderBy(familia => familia.Codigo).ToListAsync(cancellationToken);

        return new PremiosDoAluno(
            medalhas.Sum(medalha => medalha.Pontos),
            [.. familias.Select(familia => new FamiliaDoCatalogo(familia.Codigo, familia.Nome, familia.Descricao, familia.Passos))],
            [.. itens
                .Where(item => item.RestricaoCurso is null
                    || string.Equals(item.RestricaoCurso, aluno.Sigla, StringComparison.OrdinalIgnoreCase)
                    || obtidos.Contains(item.Codigo))
                .Select(item => new ItemDoAluno(
                    item.Codigo,
                    Ler<TipoDeItem>(item.Tipo),
                    item.Nome,
                    item.Descricao,
                    Ler<Tier>(item.Tier),
                    item.Pontos,
                    item.FamiliaCodigo,
                    item.OrdemNaFamilia,
                    raridades.TryGetValue(item.Codigo, out var raridade)
                        ? new RaridadeAtual(Ler<Raridade>(raridade.Raridade), raridade.AlunosComItem, raridade.AlunosElegiveis)
                        : null,
                    [.. obtidos[item.Codigo]]))]);
    }

    private static T Ler<T>(string texto)
        where T : struct, Enum =>
        NomeJson.TentarLer<T>(texto, out var valor) ? valor : throw new InvalidOperationException($"{typeof(T).Name} desconhecido: {texto}.");
}

using System.Security.Claims;
using Maxx.Api.Autenticacao;
using Maxx.Api.Medalhas;
using Maxx.Application.Premios;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Maxx.Api.Premios;

// A tela de Troféus do próprio aluno: o catálogo com o critério e a raridade, o que falta
// e o que ele já tem. Só o dono vê os faltantes (produto.md 9.1), por isso a rota é de /eu.
internal static class PremiosEndpoints
{
    public static IEndpointRouteBuilder MapPremiosEndpoints(this IEndpointRouteBuilder v1)
    {
        v1.MapGet("/eu/premios", PremiosAsync)
            .WithName("GetMeusPremios")
            .WithTags("Premios")
            .RequireAuthorization(Politicas.Aluno)
            .ProducesProblem(StatusCodes.Status403Forbidden);

        return v1;
    }

    private static async Task<Results<Ok<PremiosDoAlunoResponse>, ForbidHttpResult>> PremiosAsync(
        ClaimsPrincipal principal, IConsultaDePremios consulta, CancellationToken cancellationToken)
    {
        if (!Guid.TryParse(principal.FindFirstValue(MaxxClaims.Sub), out var id)
            || await consulta.DoAlunoAsync(id, cancellationToken) is not { } premios)
        {
            return TypedResults.Forbid();
        }

        return TypedResults.Ok(new PremiosDoAlunoResponse(
            premios.Pontos,
            [.. premios.Familias.Select(familia => new FamiliaResponse(familia.Codigo, familia.Nome, familia.Descricao, familia.Passos))],
            [.. premios.Itens.Select(item => new ItemDoAlunoResponse(
                item.Codigo,
                ProfessorEndpoints.Nome(item.Tipo),
                item.Nome,
                item.Criterio,
                ProfessorEndpoints.Nome(item.Tier),
                item.Pontos,
                item.Familia,
                item.OrdemNaFamilia,
                item.Raridade is { } raridade
                    ? new RaridadeResponse(ProfessorEndpoints.Nome(raridade.Nivel), raridade.Percentual)
                    : null,
                [.. item.Obtidos.Select(obtido => new PremioObtidoResponse(
                    obtido.Id, ProfessorEndpoints.Nome(obtido.Tier), obtido.Pontos, obtido.Materia, obtido.Bimestre, obtido.ObtidoEm))]))]));
    }
}

public sealed record PremiosDoAlunoResponse(int Pontos, IReadOnlyList<FamiliaResponse> Familias, IReadOnlyList<ItemDoAlunoResponse> Itens);

public sealed record FamiliaResponse(string Codigo, string Nome, string Descricao, int Passos);

// Tipo, tier e raridade em camelCase, como no catálogo ("premioParticipacao", "lendario").
// Critério é a descrição do item: não há prêmio secreto (produto.md 4.5).
public sealed record ItemDoAlunoResponse(
    string Codigo,
    string Tipo,
    string Nome,
    string Criterio,
    string Tier,
    int Pontos,
    string? Familia,
    int? OrdemNaFamilia,
    RaridadeResponse? Raridade,
    IReadOnlyList<PremioObtidoResponse> Obtidos);

// Percentual dos alunos que têm o item, com uma casa: "x% dos alunos".
public sealed record RaridadeResponse(string Nivel, double Percentual);

public sealed record PremioObtidoResponse(Guid Id, string Tier, int Pontos, string? Materia, int? Bimestre, DateTimeOffset ObtidoEm);

