    {
        await using var scope = factory.Services.CreateAsyncScope();
        return await scope.ServiceProvider.GetRequiredService<MaxxDbContext>().Set<Trabalho>()
            .CountAsync(trabalho => trabalho.Tipo == RecalcularRaridade.Tipo, Ct);
