import { Redirect, Slot } from "expo-router";

import { Screen } from "../../components/Screen";
import { ErrorState } from "../../components/StateMessage";
import { EsperaDaSessao } from "../../sessao/EsperaDaSessao";
import { useSessao } from "../../sessao/SessaoProvider";

// Tudo que exige login. Sem sessão, vai para o login; sem conexão para saber, explica e
// oferece tentar de novo, sem apagar a sessão guardada.
export default function AppLayout() {
  const { estado, tentarDeNovo } = useSessao();

  if (estado === "restaurando") {
    return <EsperaDaSessao />;
  }

  if (estado === "anonimo") {
    return <Redirect href="/login" />;
  }

  if (estado === "sem-conexao") {
    return (
      <Screen>
        <ErrorState
          title="Sem conexão."
          message="Confira a internet e tente de novo."
          onRetry={() => void tentarDeNovo()}
        />
      </Screen>
    );
  }

  return <Slot />;
}
import { InicioProvisorio } from "../../inicio/InicioProvisorio";

export default InicioProvisorio;
import { ActivityIndicator, StyleSheet, Text, View } from "react-native";

import { useEu } from "../api/useEu";
import { Button } from "../components/Button";
import { Screen } from "../components/Screen";
import { ErrorState } from "../components/StateMessage";
import { Logo } from "../marca/Logo";
import { useSessao } from "../sessao/SessaoProvider";
import { textStyles } from "../theme/fonts";
import { ThemePreferenceControl } from "../theme/ThemePreferenceControl";
import { useTheme } from "../theme/ThemeProvider";

// O início até o feed chegar, no passo 7: quem entrou, o tema e a saída.
export function InicioProvisorio() {
  const { colors } = useTheme();
  const { sair } = useSessao();
  const eu = useEu();

  return (
    <Screen>
      <View style={styles.coluna}>
        <Logo largura={160} />

        {eu.isPending && <ActivityIndicator color={colors.ink2} />}
        {eu.isError && <ErrorState onRetry={() => void eu.refetch()} />}
        {eu.isSuccess && (
          <View style={styles.quem}>
            <Text style={[textStyles.corpo, { color: colors.ink2 }]}>
              Você entrou como
            </Text>
            <Text
              testID="arroba"
              style={[textStyles.titulo, { color: colors.ink }]}
            >
              {eu.data.arroba}
            </Text>
            <Text
              style={[textStyles.corpo, styles.centro, { color: colors.ink2 }]}
            >
              Em breve, o seu feed aparece aqui.
            </Text>
          </View>
        )}

        <ThemePreferenceControl />
        <Button label="Sair" variant="secondary" onPress={() => void sair()} />
      </View>
    </Screen>
  );
}

const styles = StyleSheet.create({
  coluna: { flex: 1, justifyContent: "center", alignItems: "center", gap: 24 },
  quem: { alignItems: "center", gap: 4 },
  centro: { textAlign: "center" },
});
import { useQuery } from "@tanstack/react-query";

import { useApiClient } from "./ApiClientProvider";

// Quem é o dono da sessão, lido do banco pela API (o arroba pode ter mudado).
export function useEu() {
  const client = useApiClient();

  return useQuery({
    queryKey: ["eu"],
    queryFn: async () => {
      const { data, response } = await client.GET("/api/v1/eu");
      if (!data) {
        throw new Error(`GET /api/v1/eu respondeu ${response.status}.`);
      }
      return data;
    },
  });
}
import { createApiClient, type ApiClient } from "@maxx/api-client";
import { createContext, useContext, type ReactNode } from "react";
import { Platform } from "react-native";

// Origem única (ADR 0001): na web a API está no mesmo host, sob /api. No nativo, a URL
// pública vem de EXPO_PUBLIC_API_URL, que não é segredo e vai para o binário.
export function defaultBaseUrl(): string {
  return Platform.OS === "web" ? "" : (process.env.EXPO_PUBLIC_API_URL ?? "");
}

const ApiClientContext = createContext<ApiClient | null>(null);

export function ApiClientProvider({
  client,
  children,
}: {
  client: ApiClient;
  children: ReactNode;
}) {
  return (
    <ApiClientContext.Provider value={client}>
      {children}
    </ApiClientContext.Provider>
  );
}

export function useApiClient(): ApiClient {
  const client = useContext(ApiClientContext);
  if (!client) {
    throw new Error("useApiClient fora do ApiClientProvider.");
  }
  return client;
}

export { createApiClient };

