import { createRequire } from "node:module";
const require = createRequire(process.argv[2] + "/package.json");
const { chromium } = require("playwright");

const base = "http://localhost";
const saida = process.argv[3];
const senha = "senha-boa-123";
const renata = "renata.albuquerque@prof.unieduk.com.br";

async function post(caminho, corpo) {
  const r = await fetch(base + caminho, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(corpo),
  });
  return r.status;
}

const termo = await (await fetch(base + "/api/v1/termo-de-uso")).json();
const alunos = [
  ["20260104", "pedro.lima@al.unieduk.com.br", "Pedro Lima", "pedroLima"],
  ["20260105", "juliana.rocha@al.unieduk.com.br", "Juliana Rocha", "julianaRocha"],
  ["20260103", "mariana.costa@al.unieduk.com.br", "Mariana Costa", "marianaCosta"],
  ["20260102", "lucas.ferreira@al.unieduk.com.br", "Lucas Ferreira", "lucasFerreira"],
];
for (const [ra, email, nome, prefixo] of alunos) {
  console.log("cadastro", nome, await post("/api/v1/auth/cadastro", {
    ra, email, nomeDeExibicao: nome, prefixo, senha, versaoDoTermo: termo.versao,
  }));
}

// Senha da professora pelo primeiro acesso: o link chega ao Mailpit.
await fetch("http://localhost:8025/api/v1/messages", { method: "DELETE" });
console.log("recuperação", await post("/api/v1/auth/recuperacao", { email: renata }));
let token;
for (let i = 0; i < 40 && !token; i++) {
  await new Promise((r) => setTimeout(r, 500));
  const lista = await (await fetch("http://localhost:8025/api/v1/messages")).json();
  const msg = lista.messages?.find((m) => m.To[0].Address === renata);
  if (msg) {
    const texto = (await (await fetch(`http://localhost:8025/api/v1/message/${msg.ID}`)).json()).Text;
    token = /#token=([A-Za-z0-9_-]+)/.exec(texto)?.[1];
  }
}
console.log("confirmação", await post("/api/v1/auth/recuperacao/confirmar", { token, senha }));

const browser = await chromium.launch();
for (const tema of ["light", "dark"]) {
  const nome = tema === "light" ? "claro" : "escuro";
  const page = await browser.newPage({
    viewport: { width: 390, height: 844 },
    isMobile: true,
    hasTouch: true,
    colorScheme: tema,
  });
  await page.goto(base + "/login");
  await page.getByLabel(/e-mail/i).first().fill(renata);
  await page.getByLabel(/senha/i).first().fill(senha);
  await page.getByRole("button", { name: "Entrar" }).click();
  await page.getByRole("button", { name: "Minhas turmas" }).click();
  await page.getByText("Banco de Dados").waitFor();
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${saida}/turmas-${nome}.png` });

  await page.getByText("Banco de Dados").click();
  await page.getByText("Juliana Rocha").waitFor();
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${saida}/turma-${nome}.png` });

  await page.getByLabel("Conceder medalha a Juliana Rocha").click();
  await page.getByText("Para Juliana Rocha").waitFor();
  await page.getByText("Nota 10 em prova").first().click();
  await page.waitForTimeout(600);
  await page.screenshot({ path: `${saida}/modal-${nome}.png` });
  await page.close();
}
await browser.close();

