  nome: string;
  // Aviso não lido no Mural; prêmio novo em Troféus.
  novidades?: Partial<Record<"mural" | "trofeus", boolean>>;
}

const RESPIRO_NO_TOPO = 8;
// O que a aba precisa acima da área segura. Com os 34 do iPhone de referência, dá os 84.
