            novidade={
              (aba === "mural" || aba === "trofeus") && !!novidades[aba]
            }
            onPress={() => onSelect(aba)}
          >
            <Icon
              name={icone}
              size={tamanhos.iconeNav}
              color={ativa ? colors.ink : colors.ink2}
