            ? [`+${formatarNumero(pontosObtidos(item))} pts`]
            : indice === proximo
              ? [`${formatarNumero(item.pontos)} pts`, "próximo"]
              : [`${formatarNumero(item.pontos)} pts`],
        })),
      };
    });
}

