    justifyContent: "space-between",
    gap: 8,
    paddingVertical: 8,
  },
  espera: { marginTop: 32 },
  alternar: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
    minHeight: 56,
  },
  trilha: { marginBottom: 8 },
  flex: { flex: 1 },
});

