import { useQuery } from "@tanstack/react-query";

import { useApiClient } from "../api/ApiClientProvider";
import { FalhaDaApi } from "../api/FalhaDaApi";

// O catálogo do próprio aluno, com critério, raridade e o que ele já obteve. Só o dono vê
// os faltantes (produto.md 9.1): a rota é de /eu. `ativo` falso para quem não é aluno.
export function usePremios(ativo: boolean) {
  const client = useApiClient();

  return useQuery({
    queryKey: ["eu", "premios"],
    enabled: ativo,
    queryFn: async () => {
      const { data, error } = await client.GET("/api/v1/eu/premios");
      if (!data) {
        throw FalhaDaApi.doCorpo(error);
      }
      return data;
    },
  });
}

import { Pressable, StyleSheet, Text, View } from "react-native";

import { noOutline, focusRingStyle, useFocusRing } from "../components/focusRing";
import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { tamanhos } from "../theme/tokens";

interface AbasSublinhadasProps<T extends string> {
  abas: readonly { valor: T; rotulo: string }[];
  ativa: T;
  onSelect: (valor: T) => void;
}

// As abas de texto com traço embaixo da ativa, como as do perfil do Instagram e da
// prancheta de Troféus. A linha de 1 px em `line` separa do conteúdo.
export function AbasSublinhadas<T extends string>({
  abas,
  ativa,
  onSelect,
}: AbasSublinhadasProps<T>) {
  const { colors } = useTheme();

  return (
    <View
      role="tablist"
      style={[styles.barra, { borderBottomColor: colors.line }]}
    >
      {abas.map((aba) => (
        <Aba
          key={aba.valor}
          rotulo={aba.rotulo}
          ativa={aba.valor === ativa}
          onPress={() => onSelect(aba.valor)}
        />
      ))}
    </View>
  );
}

function Aba({
  rotulo,
  ativa,
  onPress,
}: {
  rotulo: string;
  ativa: boolean;
  onPress: () => void;
}) {
  const { colors } = useTheme();
  const { focusVisible, focusProps } = useFocusRing();

  return (
    <Pressable
      role="tab"
      aria-selected={ativa}
      onPress={onPress}
      {...focusProps}
      style={[styles.aba, noOutline, focusVisible && focusRingStyle(colors.focus)]}
    >
      <Text
        style={[textStyles.secao, { color: ativa ? colors.ink : colors.ink2 }]}
      >
        {rotulo}
      </Text>
      <View
        style={[
          styles.traco,
          { backgroundColor: ativa ? colors.ink : "transparent" },
        ]}
      />
    </Pressable>
  );
}

const styles = StyleSheet.create({
  barra: { flexDirection: "row", borderBottomWidth: 1 },
  aba: {
    flex: 1,
    alignItems: "center",
    justifyContent: "flex-end",
    minHeight: tamanhos.alvoDeToque,
    paddingTop: 8,
    gap: 8,
  },
  traco: { height: 2, alignSelf: "stretch", marginHorizontal: 24, borderRadius: 1 },
});

import { StyleSheet, Text, View } from "react-native";

import { Medalhao } from "../premios/Medalhao";
import { rotulosDeRaridade, rotulosDeTier } from "../premios/rotulos";
import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { tiers, type Tier } from "../theme/tokens";
import {
  detalheDaLinha,
  glifoDe,
  pontosDaLinha,
  raridadeDe,
  textoDaRaridade,
  type ItemDoAluno,
} from "./montagem";

// Uma linha da lista de Troféus (prancheta trofeus-*.png): medalhão com tier e raridade,
// nome, "Tier · Raridade · x% dos alunos", o critério ou de onde veio, e os pontos. O que
// falta aparece apagado, com o valor do catálogo sem o "+".
export function LinhaDePremio({ item }: { item: ItemDoAluno }) {
  const { colors, name } = useTheme();
  const tier = item.tier as Tier;
  const raridade = raridadeDe(item);
  const obtido = item.obtidos.length > 0;

  return (
    <View
      testID={`premio-${item.codigo}`}
      accessible
      accessibilityLabel={[
        item.nome,
        rotulosDeTier[tier],
        raridade && rotulosDeRaridade[raridade],
        obtido ? "obtido" : "não obtido",
      ]
        .filter(Boolean)
        .join(", ")}
      style={[styles.linha, { borderBottomColor: colors.line }]}
    >
      <View style={!obtido && styles.apagado}>
        <Medalhao tier={tier} glifo={glifoDe(item)} raridade={raridade} />
      </View>
      <View style={styles.texto}>
        <Text style={[textStyles.secao, { color: colors.ink }]}>{item.nome}</Text>
        <Text style={textStyles.legenda}>
          <Text style={{ color: tiers[tier].texto[name] }}>
            {rotulosDeTier[tier]}
          </Text>
          {raridade && item.raridade && (
            <Text style={{ color: colors.ink2 }}>
              {` · ${rotulosDeRaridade[raridade]} · ${textoDaRaridade(item.raridade.percentual)}`}
            </Text>
          )}
        </Text>
        <Text style={[textStyles.legenda, { color: colors.ink2 }]}>
          {detalheDaLinha(item)}
        </Text>
      </View>
      <Text
        style={[textStyles.pontos, { color: obtido ? colors.ink : colors.ink3 }]}
      >
        {pontosDaLinha(item)}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  linha: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
    paddingVertical: 14,
    borderBottomWidth: 1,
  },
