// Concede medalhas pela API (Renata a Juliana e a outros) e tira as capturas da tela de
// Troféus nas duas abas, no claro e no escuro, como a Juliana.
import { createRequire } from "node:module";
const require = createRequire(process.argv[2] + "/package.json");
const { chromium } = require("playwright");

const base = "http://localhost";
const saida = process.argv[3];
const senha = "senha-boa-123";

async function entrar(identificador) {
  const r = await fetch(base + "/api/v1/auth/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ identificador, senha }),
  });
  return (await r.json()).accessToken;
}

const renata = await entrar("renata.albuquerque@prof.unieduk.com.br");
const get = async (caminho) =>
  (await fetch(base + caminho, { headers: { Authorization: `Bearer ${renata}` } })).json();
const turmas = await get("/api/v1/professor/turmas");
for (const turma of turmas) {
  const alunos = await get(`/api/v1/professor/turmas/${turma.id}/alunos`);
  const concessoes = turma.materia === "Banco de Dados"
    ? [["juliana", "M01"], ["juliana", "M01"], ["juliana", "M03"], ["pedro", "M01"], ["mariana", "M04"]]
    : turma.materia === "Estruturas de Dados"
      ? [["juliana", "M02"], ["juliana", "M09"]]
      : [];
  for (const [quem, item] of concessoes) {
    const aluno = alunos.find((a) => a.arroba.startsWith(`@${quem}`));
    const r = await fetch(`${base}/api/v1/professor/turmas/${turma.id}/medalhas`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${renata}` },
      body: JSON.stringify({ alunoId: aluno.id, item }),
    });
    console.log(turma.materia, quem, item, r.status);
  }
}

// O worker recalcula a raridade com coalescência de dez segundos.
await new Promise((r) => setTimeout(r, 12000));

const browser = await chromium.launch();
for (const tema of ["light", "dark"]) {
  const nome = tema === "light" ? "claro" : "escuro";
  const page = await browser.newPage({
    viewport: { width: 390, height: 844 },
    isMobile: true,
    hasTouch: true,
    colorScheme: tema,
  });
  await page.goto(base + "/login");
  await page.getByLabel(/e-mail/i).first().fill("juliana.rocha@al.unieduk.com.br");
  await page.getByLabel(/senha/i).first().fill(senha);
  await page.getByRole("button", { name: "Entrar" }).click();
  await page.getByRole("tab", { name: "Troféus" }).first().click();
  await page.getByText("Mostrar não obtidos").waitFor();
  await page.waitForTimeout(800);
  await page.screenshot({ path: `${saida}/trofeus-aba-trofeus-${nome}.png` });

  await page.getByRole("tab", { name: "Medalhas" }).click();
  await page.waitForTimeout(800);
  await page.screenshot({ path: `${saida}/trofeus-aba-medalhas-${nome}.png` });
  await page.close();
}
await browser.close();

