  return sql(
    `SELECT m.id FROM medalha m
     JOIN usuario u ON u.id = m.aluno_id
     JOIN cadastro_elegivel c ON c.id = u.cadastro_elegivel_id
     WHERE c.ra = '${aluno.ra}' AND m.anulada_em IS NULL;`,
